{"content": "{
  "main_characters": [
    {
      "name": "沈宁",
      "role": "protagonist",
      "identity": "烈士遗孤，27岁，被组织安排的政治联姻对象",
      "traits": ["隐忍克制", "敏锐观察", "外冷内热", "战场幸存者创伤"],
      "overt_motivation": "完成组织安排的政治婚姻，扮演好'陆太太'的角色",
      "covert_motivation": "确认十年前那个少年是否真的死了，渴望被认出却又害怕被认出",
      "secret_fear": "承认旧情会背叛组织的安排，连累他失去前程",
      "misperception_of_other": "以为他早已在边境战场牺牲，眼前的人只是长得相似的陌生人",
      "hidden_connection": "十年前在边境战场与他相遇，他为她挡过枪，她以为他死了"
    },
    {
      "name": "陆霆",
      "role": "deuteragonist",
      "identity": "红三代，32岁，军区少将，被组织安排的政治联姻对象",
      "traits": ["冷峻克制", "忠诚服从", "内心炽热", "战场后遗症"],
      "overt_motivation": "服从组织安排完成政治婚姻，维持军人形象",
      "covert_motivation": "确认她是否还记得自己，渴望触碰她却又必须保持距离",
      "secret_fear": "承认旧情会让她陷入政治漩涡，毁掉她平静的生活",
      "misperception_of_other": "以为她当年在战场爆炸中失明或死亡，眼前的人只是组织安排的陌生妻子",
      "hidden_connection": "十年前在边境战场为她挡过枪，背上留有伤疤，以为她死了"
    }
  ],
  "supporting_characters": [
    {
      "name": "周政委",
      "function": "阻碍",
      "identity": "军区政委，政治联姻的安排者",
      "description": "代表组织意志，定期电话'关心'新婚夫妇，实则是监视"
    },
    {
      "name": "哨兵小王",
      "function": "阻碍",
      "identity": "军区大院岗哨士兵",
      "description": "定时巡逻，窗外可见的身影，象征外部监视压力"
    }
  ],
  "relationship_dynamics": "两人是十年前边境战场的青梅竹马，都曾以为对方已死。十年后以政治联姻的方式重逢，却必须装作陌生。他们的关系在'伪装陌生→暗语试探→伤疤确认→共犯偷情'中层层递进，每一次靠近都伴随着被发现的危险。战场暗语成为他们唯一的私密语言，那些曾经用来杀人的手势，现在用来表达爱意。"
}", "path": "characters.json"}

{"content": "{
  "act_one": {
    "description": "新婚夜，两人在军区大院新房初次以'夫妻'身份见面，震惊发现彼此是以为已死的青梅竹马，但必须装作陌生。建立外部监视压力（岗哨、电话），完成第一次关键接触。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "红妆与军装",
        "core_event": "新婚夜，沈宁与陆霆在军区大院新房见面，两人震惊发现彼此是以为已死的青梅竹马，但必须装作陌生。",
        "emotional_tone": "震惊、压抑、克制",
        "key_scenes": ["推开新房门的瞬间，红色喜字与军绿色窗帘的对比", "两人对视时瞳孔的收缩，随即移开视线", "周政委的电话'关心'，实则是监视", "结婚证被放在床头柜上，照片NG了十遍才过审"]
      }
    ],
    "turning_point": "陆霆脱下军装时，沈宁瞥见他背上的伤疤——那是十年前在边境战场为她挡枪的位置。"
  },
  "act_two": {
    "description": "冲突螺旋升级：外部监视压力（哨兵巡逻、电话监听）与内部情感崩解（暗语试探、伤疤确认）交织，两人从伪装陌生到用战场暗语交流，最终做出不可逆的行为。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "暗语",
        "core_event": "陆霆用手势比出一个战场暗语，沈宁下意识回应，两人瞬间确认彼此身份，但随即恢复陌生表情。",
        "emotional_tone": "试探、紧张、暗流涌动",
        "key_scenes": ["陆霆倒水时手指的细微动作——那是'安全'的手势", "沈宁手指颤抖，比出'危险'的回应", "两人对视，眼神中有千言万语，但嘴上说的是'水温合适吗'", "窗外哨兵的脚步声经过，两人同时静止"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "伤疤",
        "core_event": "沈宁确认陆霆背上的伤疤是当年为她挡枪留下的，陆霆却说是'训练中受伤'，沈宁崩溃但必须压抑。",
        "emotional_tone": "痛苦、压抑、濒临爆发",
        "key_scenes": ["沈宁借口帮他整理衣服，手指触碰到他背上的伤疤", "陆霆身体僵硬，说'训练伤的，不值一提'", "沈宁知道他在说谎——那伤疤的形状和位置，她记得太清楚", "她转身去浴室，在镜子里咬住自己的手背不让自己哭出声"]
      }
    ],
    "turning_point": "哨兵巡逻的间隙只有三分钟，陆霆用手势问'要不要'，沈宁沉默两秒后，比出'要'。"
  },
  "act_three": {
    "description": "高潮：两人在哨兵巡逻的间隙安静做爱，用战场暗语交流，那些曾经用来杀人的手势现在用来表达爱意。结局：清晨，新的默契建立，结婚证从政治文件变成他们之间的情书。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "三分钟",
        "core_event": "哨兵巡逻的间隙只有三分钟，两人在极度压抑中完成第一次真正的亲密接触，全程无声，只有手势和眼神交流。",
        "emotional_tone": "压抑的爆发、禁忌、痛苦与快感交织",
        "key_scenes": ["陆霆用手势倒数：三、二、一", "沈宁主动吻上去，手捂住他的嘴不让自己出声", "军装被褪到一半，伤疤暴露在红色喜被上", "窗外哨兵的脚步声再次响起，两人静止，维持着交缠的姿势", "脚步声远去，他们继续，比之前更疯狂"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "晨光",
        "core_event": "清晨，两人穿戴整齐，恢复'陆先生陆太太'的身份，但结婚证被沈宁翻到背面，用口红写了一个小小的暗语符号。",
        "emotional_tone": "压抑后的平静、新的默契、物件回扣",
        "key_scenes": ["陆霆穿好军装，扣子一颗颗扣好，恢复冷峻少将的模样", "沈宁整理好头发，遮住脖子上的吻痕", "两人对视，陆霆比出一个'等我回来'的手势", "沈宁拿起结婚证，翻到背面，用口红写了一个小小的'安'字——那是他们之间的暗语，意思是'我还活着，等你'", "窗外哨兵换岗，新的一天开始，他们继续扮演陌生夫妻，但有什么东西已经永远改变了"]
      }
    ],
    "turning_point": "结婚证背面的口红暗语——政治文件变成了情书，他们成为共犯，在组织的监视下偷取属于彼此的时间。"
  }
}", "path": "outline.json"}

